def git(ref,p):return subprocess.check_output(['git','show',ref+':'+p],cwd=ROOT).decode()
def block(s,pattern):
 m=re.search(pattern,s);assert m,pattern
 tag=re.match(r'<([\w:-]+)',m.group()).group(1);depth=0
 for t in re.finditer(r'<!--[\s\S]*?-->|</?([\w:-]+)\b[^>]*>',s[m.start():]):
  v=t.group()
  if v.startswith('<!--') or t.group(1)!=tag:continue
  if v.startswith('</'):depth-=1
  elif not v.endswith('/>'):depth+=1
  if depth==0:return s[m.start():m.start()+t.end()]
 raise ValueError(pattern)
def sec(s,id):return block(s,rf'<section\b[^>]*\bid="{id}"[^>]*>')
def replace1(s,old,new):assert s.count(old)==1,(old[:100],s.count(old));return s.replace(old,new,1)
def h2(id,top,end,ru,cls='sec-title'):
 return f'<div class="r1p-title-group"><h2 id="{id}" class="{cls}" lang="en">{top}<br><em>{end}</em></h2><p class="r1p-translation" lang="ru">{ru}</p></div>'
