mods=mods.replace('DRAFT · v0.12','МОДЕЛЬ ЧТЕНИЯ').replace('PROLOGUE_00','CHRONICLE').replace('Protocol Ω','Главы').replace('Deaf Station','Фрагменты').replace('World After<br/>Black Sun','World After<br/>Black Sun')
mods=mods.replace('[CHR-WHITE-CONTOUR-0317]','ПРИМЕР СТРУКТУРЫ').replace('V1.0','ОБРАЗЕЦ').replace('White Contour','СУЩНОСТЬ МИРА').replace('CLASS·<b>ANOMALY</b>','ТИП·<b>ДОСЬЕ</b>').replace('STATE·<b>PUBLISHED</b>','ВИД·<b>МОДЕЛЬ</b>')
