feet=re.findall(r'<div class="m-foot">[\s\S]*?</div>',mods)
footnew=[('ЧТЕНИЕ','ОРБИТА','КОНТЕКСТ','ГЛАВА','МОДЕЛЬ','CHRONICLE'),('ЗАПИСЬ','ДОСЬЕ','СВЯЗИ','КОНТЕКСТ','МОДЕЛЬ','CONTENT'),('ОСНОВА','CANON','СВЯЗИ','МАРШРУТЫ','МОДЕЛЬ','CARTOGRAPHY'),('ВИЗУАЛ','РАДАР','КОНТЕКСТ','ЛОКАЦИИ','МОДЕЛЬ','WATCH_DOG')]
